_loadNetSet = new std::set<ndmNet*, ndmObjPtrCmpType>();
// and/or canonicalize return:
return drvTerms.empty() ? nullptr : *drvTerms.begin(); // termSetType already uses ndmObjPtrCmpType
```
Prefer returning a deterministic pick from the accumulated `drvTerms` (e.g. `getTopLevelDrvTerm(drvTerms)`) instead of last loadNetSet iterator.

Version A — strict weak order with stable tiebreak:
```cpp
struct compareTimInfo {
  bool operator()(const timingInfo* a, const timingInfo* b) const {
    int c = nwmathFloat::compare(a->getScore(), b->getScore(), 0.0001);
    if (c != 0) return c < 0; // ascending score (worst first)
    ndmTerm* ta = const_cast<timingInfo*>(a)->getTerm();
    ndmTerm* tb = const_cast<timingInfo*>(b)->getTerm();
    return ndmObjectHandleNS::compareObjPtr{}(ta, tb); // or getIdLong()
  }
};
```

